-- Generated only from frozen current-account-visible reference captures. Do not hand edit.
ALTER TABLE detection_standard DROP CONSTRAINT detection_standard_status_check;
ALTER TABLE detection_standard DROP CONSTRAINT detection_standard_source_system_source_key_key;
ALTER TABLE detection_standard
  ADD COLUMN series_id uuid,
  ADD COLUMN predecessor_id uuid REFERENCES detection_standard(id),
  ADD COLUMN revision_number integer,
  ADD COLUMN state varchar(16),
  ADD COLUMN ownership_type varchar(24),
  ADD COLUMN basis_type varchar(24),
  ADD COLUMN standard_type varchar(24),
  ADD COLUMN issuing_institution varchar(240),
  ADD COLUMN cited_basis varchar(1000),
  ADD COLUMN effective_date date,
  ADD COLUMN repeal_date date,
  ADD COLUMN document_file_id uuid REFERENCES stored_file(id),
  ADD COLUMN source_record_id varchar(80),
  ADD COLUMN source_path varchar(500),
  ADD COLUMN source_captured_at timestamptz,
  ADD COLUMN content_sha256 char(64),
  ADD COLUMN source_attachment_count integer NOT NULL DEFAULT 0,
  ADD COLUMN source_validation_warning varchar(500),
  ADD COLUMN created_by uuid REFERENCES app_user(id),
  ADD COLUMN updated_by uuid REFERENCES app_user(id),
  ADD COLUMN published_at timestamptz;
UPDATE detection_standard SET series_id=id, revision_number=1, state='PUBLISHED', status='CURRENT',
  ownership_type='SYSTEM', basis_type='DETECTION', standard_type='OTHER', published_at=created_at;
ALTER TABLE detection_standard
  ALTER COLUMN series_id SET NOT NULL,
  ALTER COLUMN revision_number SET NOT NULL,
  ALTER COLUMN state SET NOT NULL,
  ALTER COLUMN ownership_type SET NOT NULL,
  ALTER COLUMN basis_type SET NOT NULL,
  ALTER COLUMN standard_type SET NOT NULL,
  ADD CONSTRAINT detection_standard_revision_ck CHECK (revision_number > 0),
  ADD CONSTRAINT detection_standard_state_ck CHECK (state IN ('DRAFT','PUBLISHED','RETIRED')),
  ADD CONSTRAINT detection_standard_status_ck CHECK (status IN ('CURRENT','UPCOMING','REPEALED')),
  ADD CONSTRAINT detection_standard_ownership_ck CHECK (ownership_type IN ('SYSTEM','ORGANIZATION')),
  ADD CONSTRAINT detection_standard_basis_ck CHECK (basis_type IN ('DETECTION','JUDGEMENT','BOTH')),
  ADD CONSTRAINT detection_standard_type_ck CHECK (standard_type IN ('NATIONAL','INDUSTRY','LOCAL','ASSOCIATION','ENTERPRISE','OTHER')),
  ADD CONSTRAINT detection_standard_dates_ck CHECK (
    source_validation_warning IS NOT NULL OR repeal_date IS NULL OR repeal_date >= effective_date),
  ADD CONSTRAINT detection_standard_source_revision_uk UNIQUE (source_system, source_key, revision_number),
  ADD CONSTRAINT detection_standard_series_revision_uk UNIQUE (series_id, revision_number);
CREATE UNIQUE INDEX detection_standard_one_draft_ix ON detection_standard(series_id) WHERE state='DRAFT';
CREATE UNIQUE INDEX detection_standard_one_published_ix ON detection_standard(series_id) WHERE state='PUBLISHED';
CREATE INDEX detection_standard_list_ix ON detection_standard(updated_at DESC, id DESC);
CREATE INDEX detection_standard_filter_ix ON detection_standard(state, status, basis_type, standard_type, effective_date, code);

CREATE TABLE detection_standard_parameter_scope (
  standard_id uuid NOT NULL REFERENCES detection_standard(id) ON DELETE CASCADE,
  parameter_id uuid NOT NULL REFERENCES test_parameter(id),
  PRIMARY KEY (standard_id, parameter_id)
);
CREATE INDEX detection_standard_parameter_scope_parameter_ix ON detection_standard_parameter_scope(parameter_id, standard_id);

CREATE TABLE reference_configuration_import_manifest (
  resource_type varchar(40) NOT NULL,
  source_system varchar(40) NOT NULL,
  capture_sha256 char(64) NOT NULL,
  source_captured_at timestamptz NOT NULL,
  record_count integer NOT NULL,
  imported_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (resource_type, source_system, capture_sha256)
);

CREATE TABLE numbering_flow_rule (
  id uuid PRIMARY KEY,
  series_id uuid NOT NULL,
  predecessor_id uuid REFERENCES numbering_flow_rule(id),
  revision_number integer NOT NULL CHECK (revision_number > 0),
  code varchar(80),
  name varchar(240) NOT NULL,
  auto_match_project_code boolean NOT NULL DEFAULT false,
  state varchar(16) NOT NULL CHECK (state IN ('DRAFT','PUBLISHED','RETIRED')),
  lock_version bigint NOT NULL DEFAULT 0,
  source_system varchar(40),
  source_record_id varchar(80),
  source_path varchar(500),
  source_captured_at timestamptz,
  content_sha256 char(64),
  created_by uuid REFERENCES app_user(id),
  updated_by uuid REFERENCES app_user(id),
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (series_id, revision_number),
  UNIQUE (source_system, source_record_id, revision_number)
);
CREATE UNIQUE INDEX numbering_flow_rule_one_draft_ix ON numbering_flow_rule(series_id) WHERE state='DRAFT';
CREATE UNIQUE INDEX numbering_flow_rule_one_published_ix ON numbering_flow_rule(series_id) WHERE state='PUBLISHED';
CREATE UNIQUE INDEX numbering_flow_rule_published_code_ix ON numbering_flow_rule(lower(code))
  WHERE state='PUBLISHED' AND code IS NOT NULL;
CREATE INDEX numbering_flow_rule_list_ix ON numbering_flow_rule(updated_at DESC, id DESC);

CREATE TABLE numbering_flow_rule_pattern (
  rule_id uuid NOT NULL REFERENCES numbering_flow_rule(id) ON DELETE CASCADE,
  resource_type varchar(16) NOT NULL CHECK (resource_type IN ('COMMISSION','SAMPLE','TASK','REPORT')),
  generation_mode varchar(32) NOT NULL CHECK (generation_mode IN ('SEPARATE','SAME_AS_COMMISSION','REPLACE_PREFIX','REMOVE_PREFIX')),
  sequence_scope varchar(24) NOT NULL CHECK (sequence_scope IN ('SHARED','PER_PROJECT')),
  seed varchar(80),
  pattern varchar(240) NOT NULL,
  sort_order integer NOT NULL,
  PRIMARY KEY (rule_id, resource_type)
);

CREATE TABLE numbering_flow_rule_project (
  rule_id uuid NOT NULL REFERENCES numbering_flow_rule(id) ON DELETE CASCADE,
  project_node_id uuid NOT NULL REFERENCES detection_catalog_node(id),
  PRIMARY KEY (rule_id, project_node_id)
);
CREATE INDEX numbering_flow_rule_project_project_ix ON numbering_flow_rule_project(project_node_id, rule_id);

CREATE TABLE numbering_flow_template (
  id uuid PRIMARY KEY,
  series_id uuid NOT NULL,
  predecessor_id uuid REFERENCES numbering_flow_template(id),
  revision_number integer NOT NULL CHECK (revision_number > 0),
  code varchar(80) NOT NULL,
  name varchar(240) NOT NULL,
  prefix varchar(160) NOT NULL DEFAULT '',
  prefix_position varchar(24),
  date_pattern varchar(16) NOT NULL,
  suffix varchar(160),
  suffix_position varchar(24),
  sequence_width integer NOT NULL CHECK (sequence_width BETWEEN 1 AND 12),
  state varchar(16) NOT NULL CHECK (state IN ('DRAFT','PUBLISHED','RETIRED')),
  lock_version bigint NOT NULL DEFAULT 0,
  source_system varchar(40),
  source_record_id varchar(80),
  source_path varchar(500),
  source_captured_at timestamptz,
  content_sha256 char(64),
  created_by uuid REFERENCES app_user(id),
  updated_by uuid REFERENCES app_user(id),
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (series_id, revision_number),
  UNIQUE (source_system, source_record_id, revision_number)
);
CREATE UNIQUE INDEX numbering_flow_template_one_draft_ix ON numbering_flow_template(series_id) WHERE state='DRAFT';
CREATE UNIQUE INDEX numbering_flow_template_one_published_ix ON numbering_flow_template(series_id) WHERE state='PUBLISHED';
CREATE UNIQUE INDEX numbering_flow_template_published_code_ix ON numbering_flow_template(lower(code)) WHERE state='PUBLISHED';
CREATE INDEX numbering_flow_template_list_ix ON numbering_flow_template(updated_at DESC, id DESC);

